-- 2. Seed Scenario & Version 1 (Schema: scenario)
DECLARE @ScenarioId_FIN_001_V1 int;
SELECT @ScenarioId_FIN_001_V1 = [Id] FROM [scenario].[Scenarios] WHERE [Code] = N'FIN-001';
IF @ScenarioId_FIN_001_V1 IS NULL
BEGIN
    INSERT INTO [scenario].[Scenarios] ([ApplicationId], [CreatedByUserId], [Code], [Title], [Description], [Status], [CreatedAt])
    VALUES (@ApplicationId_FIN_001_V1, @InstructorUserId_FIN_001_V1, N'FIN-001', N'FinNova - Tự động hóa Phê duyệt Khoản vay Tiêu dùng Trực tuyến & Chống Gian lận eKYC', N'Learner đóng vai trò Senior Lead FinTech BA, khảo sát luồng khởi tạo khoản vay số, phỏng vấn 5 bên liên quan, ứng phó biến cố tấn công Deepfake bầy đàn và đặc tả hệ thống Digital LOS chuẩn mực.', N'Published', SYSDATETIMEOFFSET());
    SET @ScenarioId_FIN_001_V1 = SCOPE_IDENTITY();
END;

DECLARE @ScenarioVersionId_FIN_001_V1 int;
SELECT @ScenarioVersionId_FIN_001_V1 = [Id] FROM [scenario].[ScenarioVersions] WHERE [ScenarioId] = @ScenarioId_FIN_001_V1 AND [VersionNo] = 1;
IF @ScenarioVersionId_FIN_001_V1 IS NULL
BEGIN
    INSERT INTO [scenario].[ScenarioVersions] (
        [ScenarioId], [VersionNo], [Summary], [BusinessContext], [BusinessProblem], [BusinessObjectives],
        [BARole], [Assignment], [InScope], [OutOfScope], [KnownConstraints], [Difficulty], [Status], [IsPublished], [PublishedAt], [CreatedAt]
    ) VALUES (
        @ScenarioId_FIN_001_V1, 1, N'Thiết kế lại nền tảng Digital LOS tích hợp eKYC Liveness, đối soát dữ liệu dân cư và tự động hóa quy trình phê duyệt tín dụng tức thì (STP) trong 5 phút của FinNova Finance.', N'FinNova là công ty tài chính tiêu dùng số hàng đầu, cung cấp các sản phẩm vay tín chấp nhanh (Cash Loan) từ 10 đến 70 triệu VNĐ phục vụ phân khúc khách hàng trẻ qua ứng dụng di động FinNova Cash. Hệ thống tiếp nhận trung bình 15.000 hồ sơ vay mỗi ngày. Để cạnh tranh với các đối thủ Fintech và ngân hàng số, FinNova đặt mục tiêu cam kết phê duyệt và giải ngân tự động trong vòng 5 phút (Fast Disbursal). Tuy nhiên, kiến trúc hệ thống hiện tại là sự kết hợp giữa các module mua ngoài và các bước thẩm định thủ công qua điện thoại, tạo ra điểm nghẽn nghiêm trọng và kẽ hở cho tội phạm có tổ chức trục lợi.', N'1. Gian lận danh tính tinh vi: Tội phạm công nghệ cao sử dụng CCCD giả mạo, ảnh chụp màn hình hoặc công nghệ Deepfake khuôn mặt để vượt qua bước xác thực eKYC. Thiệt hại do nợ xấu gian lận (Fraud Losses) tăng đột biến, chiếm hơn 2.8% tổng dư nợ cho vay mới. 2. Nghẽn khâu thẩm định thủ công: Tỷ lệ hồ sơ được phê duyệt thẳng tự động (Straight-Through Processing - STP) chỉ đạt 22%. Gần 78% hồ sơ rơi vào trạng thái "Cần kiểm tra thủ công", khiến đội ngũ 120 nhân viên thẩm định bị quá tải, kéo dài thời gian phê duyệt trung bình từ 5 phút lên 18 đến 36 giờ, làm hơn 35% khách hàng chất lượng tốt bỏ cuộc giữa chừng. 3. Mâu thuẫn dữ liệu thu nhập và kiểm tra chéo: Khách hàng làm việc tự do (Gig Economy) không có sao kê lương ngân hàng truyền thống, trong khi quy định tín dụng cũ bắt buộc phải có hợp đồng lao động hoặc hóa đơn điện nước chính chủ, dẫn tới việc từ chối oan uổng (False Positives) nhiều khách hàng tiềm năng. 4. Độ trễ và chi phí tra cứu cổng thông tin tín dụng CIC: Mỗi lượt truy vấn API sang Trung tâm Thông tin Tín dụng Quốc gia (CIC) tốn chi phí và mất từ 30 giây đến 3 phút. Nếu hồ sơ vay bị rớt ngay ở bước thẩm định ban đầu nhưng vẫn gọi API CIC sẽ gây lãng phí ngân sách hàng trăm triệu đồng mỗi tháng.', N'1. Nâng tỷ lệ phê duyệt thẳng không cần can thiệp thủ công (STP Rate) từ 22% lên tối thiểu 65% cho phân khúc khách hàng có điểm tín nhiệm trung bình-khá trở lên. 2. Rút ngắn thời gian xử lý hồ sơ vay từ bước đăng ký đến khi có kết quả phê duyệt cuối cùng xuống dưới 5 phút cho các hồ sơ đạt chuẩn STP. 3. Ngăn chặn tối thiểu 95% các vụ gian lận mạo danh eKYC thông qua việc tích hợp xác thực khuôn mặt động (Liveness Detection chuẩn iBeta Level 2) và đối soát dữ liệu định danh dân cư. 4. Giảm 30% chi phí tra cứu dữ liệu bên thứ ba bằng cách xây dựng phễu sàng lọc dữ liệu nhiều tầng (Multi-tier Filtering Funnel).',
        N'Bạn là Senior Lead FinTech Business Analyst chịu trách nhiệm khảo sát toàn diện luồng nghiệp vụ tín dụng số, phỏng vấn 5 Stakeholder chủ chốt (Credit Risk Lead, Business Director, Fraud Prevention Lead, Legal & Compliance Manager, Enterprise Architect), xử lý các biến cố gian lận công nghệ cao và hoàn thiện bộ hồ sơ bàn giao tiêu chuẩn chuẩn BABOK v3.', N'Trong vai trò Senior Business Analyst, bạn phụ trách dẫn dắt dự án phân tích qua 4 Sprints: - Sprint 1: Lập Kế hoạch BA (BAP), phân tích ma trận bên liên quan (Stakeholder Register) và kế hoạch phỏng vấn chuyên sâu 5 phòng ban. - Sprint 2: Phỏng vấn 5 AI Stakeholders (Rủi ro, Kinh doanh, Chống gian lận, Pháp chế, Kiến trúc IT), khơi gợi các mâu thuẫn giữa tốc độ giải ngân và an toàn tín dụng, chuẩn hóa BRD v1 kèm 5 Business Rules. - Sprint 3: Tiếp nhận Biến cố tấn công Deepfake bầy đàn từ nhóm tội phạm có tổ chức, hiệu chỉnh BRD v2 và xây dựng Đặc tả yêu cầu phần mềm (SRS v1) cho Decision Engine và luồng eKYC. - Sprint 4: Ứng phó sự cố cổng API CIC quá tải và Ngân hàng Nhà nước siết trần lãi suất, lập Báo cáo phân tích tác động (Impact Analysis), hoàn thiện SRS v2 và Ma trận truy vết yêu cầu (RTM) đầu-cuối.', N'- Khảo sát và thiết kế lại toàn diện luồng hành trình khách hàng vay số (Digital Customer Journey): Đăng ký, chụp ảnh giấy tờ, xác thực eKYC khuôn mặt, đối soát tài khoản thụ hưởng, ký hợp đồng điện tử bằng OTP. - Thiết kế kiến trúc Phễu thẩm định đa tầng (Multi-tier Funnel) và Ma trận ra quyết định tín dụng tự động (Credit Decision Matrix). - Tích hợp các dịch vụ API bên ngoài: eKYC, Chấm điểm viễn thông, Tra cứu thông tin tín dụng CIC. - Xây dựng bộ tài liệu bàn giao tiêu chuẩn BABOK v3 (BAP, BRD, SRS, User Stories, RTM).', N'- Không thay thế hệ thống tài chính kế toán lõi Core Banking hiện có. - Không trực tiếp xây dựng hoặc đào tạo lại mô hình Machine Learning Credit Scorecard (chỉ đặc tả luồng tích hợp và tham số). - Không can thiệp vào quy trình đôn đốc và thu hồi nợ hiện trường (Field Collection).', N'- Ràng buộc pháp lý tài chính: Bắt buộc tuân thủ Thông tư của Ngân hàng Nhà nước về an toàn bảo mật cho vay trực tuyến, Nghị định 13/2023/NĐ-CP về bảo vệ dữ liệu cá nhân (PDPD) và Luật Giao dịch Điện tử. - Ràng buộc an ninh dữ liệu: Toàn bộ thông tin định danh (PII) phải được mã hóa AES-256 ở trạng thái lưu trữ và TLS 1.3 khi truyền nhận; không được lưu trữ video eKYC ngoài vùng dữ liệu Việt Nam. - Ràng buộc hiệu năng: Thời gian phản hồi của Decision Engine nội bộ phải dưới 3 giây/hồ sơ để đảm bảo SLA tổng dưới 5 phút.', N'Advanced', N'Published', 1, SYSDATETIMEOFFSET(), SYSDATETIMEOFFSET()
    );
    SET @ScenarioVersionId_FIN_001_V1 = SCOPE_IDENTITY();
END;

-- 3. Seed Stakeholder Personas
IF NOT EXISTS (SELECT 1 FROM [scenario].[StakeholderPersonas] WHERE [ScenarioVersionId] = @ScenarioVersionId_FIN_001_V1 AND [Name] = N'Ngô Thanh Tùng')
BEGIN
    INSERT INTO [scenario].[StakeholderPersonas] (
        [ScenarioVersionId], [Name], [StakeholderRole], [Department], [Responsibilities],
        [Goals], [PainPoints], [BusinessConcerns], [CommunicationStyle], [Personality], [DisplayOrder], [IsActive]
    ) VALUES (
        @ScenarioVersionId_FIN_001_V1, N'Ngô Thanh Tùng', N'Fintech Enterprise Architect & CISO', N'Công nghệ thông tin & An ninh mạng', N'Thiết kế kiến trúc tổng thể của nền tảng Digital LOS, quản trị kết nối API Gateway bảo mật và đảm bảo tính sẵn sàng cao (High Availability) cho hệ thống giải ngân.',
        N'Xây dựng kiến trúc vi dịch vụ mở rộng linh hoạt, độ trễ xử lý Decision Engine < 3 giây/hồ sơ, chịu tải tối thiểu 2.000 hồ sơ vay đồng thời. Thiết lập cơ chế bảo vệ mạch điện (Circuit Breaker) chống sập hệ thống khi các API tra cứu bên thứ ba (CIC, Viễn thông) bị nghẽn.', N'Các nhà cung cấp giải pháp API bên ngoài thường xuyên bị chập chờn hoặc phản hồi quá 10 giây làm treo hàng đợi xử lý của FinNova. Hệ thống phải hứng chịu hàng nghìn lượt quét lỗ hổng và tấn công dò quét API từ các dải IP nước ngoài mỗi ngày.', N'Nguy cơ rò rỉ cơ sở dữ liệu khách hàng vay ra bên ngoài nếu phân quyền API Gateway lỏng lẻo; chi phí Cloud phình to do các truy vấn API không tối ưu.', N'Trầm tĩnh, khoa học, tư duy logic dựa trên các mô hình kiến trúc chuẩn (Zero Trust, Event-driven, Microservices, TLS 1.3, Kafka, Redis).', N'Khách quan, đam mê kiến trúc hệ thống bền vững, chỉ tin tưởng vào các thông số benchmark và cơ chế an toàn dự phòng đã được kiểm thử.', 5, 1
    );
END;
IF NOT EXISTS (SELECT 1 FROM [scenario].[StakeholderPersonas] WHERE [ScenarioVersionId] = @ScenarioVersionId_FIN_001_V1 AND [Name] = N'Trần Thanh Sơn')
BEGIN
    INSERT INTO [scenario].[StakeholderPersonas] (
        [ScenarioVersionId], [Name], [StakeholderRole], [Department], [Responsibilities],
        [Goals], [PainPoints], [BusinessConcerns], [CommunicationStyle], [Personality], [DisplayOrder], [IsActive]
    ) VALUES (
        @ScenarioVersionId_FIN_001_V1, N'Trần Thanh Sơn', N'Digital Lending Business Director', N'Phát triển Kinh doanh Số', N'Thúc đẩy tăng trưởng doanh số giải ngân cho vay tiêu dùng, tối ưu hóa tỷ lệ chuyển đổi trên Mobile App và mở rộng thị phần khách hàng số.',
        N'Đạt mốc giải ngân tối thiểu 150 tỷ VNĐ/tháng; tỷ lệ hoàn tất hồ sơ vay đạt > 60%. Cam kết phê duyệt và tiền về tài khoản ngân hàng trong vòng tối đa 5 phút cho khách hàng phổ thông.', N'Khách hàng tải App về nhưng bỏ cuộc giữa chừng vì form đăng ký bắt khai báo quá nhiều thứ (bắt nhập tên 3 người thân, tải 4 loại hóa đơn). Bị các đối thủ cạnh tranh cướp khách vì thời gian phê duyệt bị treo cả ngày chờ nhân viên thẩm định gọi điện.', N'Chi phí thu hút người dùng mới (Customer Acquisition Cost) quá cao; nếu quy trình phức tạp thì ngân sách quảng cáo marketing bị lãng phí hoàn toàn.', N'Hào sảng, tốc độ, dùng nhiều thuật ngữ phát triển sản phẩm công nghệ (Frictionless, Drop-off Rate, Funnel Optimization, Disbursal Speed).', N'Năng động, hướng tới kết quả, ghét thủ tục giấy tờ rườm rà, luôn đặt câu hỏi: "Làm sao để khách hàng chỉ cần chạm 3 lần là nhận được tiền?".', 2, 1
    );
END;
IF NOT EXISTS (SELECT 1 FROM [scenario].[StakeholderPersonas] WHERE [ScenarioVersionId] = @ScenarioVersionId_FIN_001_V1 AND [Name] = N'Lê Kim Oanh')
BEGIN
    INSERT INTO [scenario].[StakeholderPersonas] (
        [ScenarioVersionId], [Name], [StakeholderRole], [Department], [Responsibilities],
        [Goals], [PainPoints], [BusinessConcerns], [CommunicationStyle], [Personality], [DisplayOrder], [IsActive]
    ) VALUES (
        @ScenarioVersionId_FIN_001_V1, N'Lê Kim Oanh', N'Underwriting & Fraud Prevention Lead', N'Thẩm định Tín dụng & Phòng chống Gian lận', N'Quản trị đội ngũ 120 thẩm định viên hồ sơ, kiểm soát các vụ việc gian lận mạo danh eKYC và xây dựng danh sách đen gian lận (Fraud Blacklist).',
        N'Chặn đứng 100% các thủ đoạn mạo danh khuôn mặt (Deepfake, mặt nạ in 3D, camera ảo) và CCCD đục góc gắn chip giả. Tự động hóa các bước kiểm tra dấu hiệu gian lận thiết bị (Device Fingerprinting) để giảm tải làm thêm giờ cho nhân viên.', N'Đội ngũ thẩm định viên bị quá tải nghiêm trọng, phải soi từng chi tiết mờ nhòe trên ảnh giấy tờ đến 21h đêm; tỷ lệ sai sót tăng cao do mỏi mắt. Bọn tội phạm liên tục thay đổi thủ đoạn, dùng số điện thoại rác và định vị GPS ảo để tạo hàng loạt hồ sơ vay cùng lúc.', N'Nguy cơ nhân viên thẩm định bị các đối tượng môi giới bên ngoài mua chuộc để thông đồng phê duyệt hồ sơ vay "ma" chia hoa hồng.', N'Sắc sảo, thực tế, luôn nêu ra các ví dụ cụ thể về chiêu trò lừa đảo và các thủ đoạn qua mặt camera điện thoại.', N'Đa nghi, tỉ mỉ, có trực giác điều tra xuất sắc, luôn cảnh giác với các chỉ số "tăng trưởng thần tốc" của bộ phận kinh doanh.', 3, 1
    );
END;
IF NOT EXISTS (SELECT 1 FROM [scenario].[StakeholderPersonas] WHERE [ScenarioVersionId] = @ScenarioVersionId_FIN_001_V1 AND [Name] = N'Phạm Quốc Huy')
BEGIN
    INSERT INTO [scenario].[StakeholderPersonas] (
        [ScenarioVersionId], [Name], [StakeholderRole], [Department], [Responsibilities],
        [Goals], [PainPoints], [BusinessConcerns], [CommunicationStyle], [Personality], [DisplayOrder], [IsActive]
    ) VALUES (
        @ScenarioVersionId_FIN_001_V1, N'Phạm Quốc Huy', N'Legal & Compliance Manager', N'Pháp chế & Tuân thủ', N'Giám sát việc tuân thủ các quy định của Ngân hàng Nhà nước, Luật Bảo vệ người tiêu dùng và Nghị định 13/2023/NĐ-CP về bảo vệ dữ liệu cá nhân (PDPD).',
        N'Đảm bảo 100% hợp đồng vay điện tử có giá trị pháp lý vững chắc trước tòa án khi phát sinh tranh chấp hoặc khởi kiện thu hồi nợ. Bảo đảm FinNova không bị cơ quan chức năng xử phạt hành chính về vi phạm thu thập dữ liệu cá nhân trái phép.', N'Đội ngũ kinh doanh liên tục tự ý tích hợp SDK thu thập dữ liệu danh bạ và nhật ký cuộc gọi của khách hàng mà không có sự đồng ý minh thị rõ ràng (Consent). Hợp đồng điện tử ký qua App nếu làm quá sơ sài bằng một nút bấm sẽ bị tòa án tuyên vô hiệu khi khách hàng chối bỏ trách nhiệm vay.', N'Rủi ro bị tước giấy phép kinh doanh tài chính tiêu dùng hoặc bị khách hàng kiện tập thể do làm lộ lọt dữ liệu tài chính nhạy cảm.', N'Chuẩn mực pháp lý, điềm đạm, luôn đặt câu hỏi về căn cứ luật định: "Quy trình này đã có điều khoản miễn trừ trách nhiệm chưa? Căn cứ pháp lý tại điều khoản nào?".', N'Thượng tôn pháp luật, cẩn trọng tuyệt đối, không thỏa hiệp trước các đề xuất đốt cháy giai đoạn ký kết hợp đồng.', 4, 1
    );
END;
IF NOT EXISTS (SELECT 1 FROM [scenario].[StakeholderPersonas] WHERE [ScenarioVersionId] = @ScenarioVersionId_FIN_001_V1 AND [Name] = N'Nguyễn Trí Dũng')
BEGIN
    INSERT INTO [scenario].[StakeholderPersonas] (
        [ScenarioVersionId], [Name], [StakeholderRole], [Department], [Responsibilities],
        [Goals], [PainPoints], [BusinessConcerns], [CommunicationStyle], [Personality], [DisplayOrder], [IsActive]
    ) VALUES (
        @ScenarioVersionId_FIN_001_V1, N'Nguyễn Trí Dũng', N'Credit Risk Management Lead', N'Quản trị Rủi ro Tín dụng', N'Xây dựng chính sách tín dụng, thiết lập ngưỡng điểm cắt phê duyệt (Cut-off Score), theo dõi chất lượng danh mục nợ và tỷ lệ nợ xấu (NPL).',
        N'Khống chế tỷ lệ nợ xấu toàn danh mục cho vay dưới 3.5%. Đảm bảo mọi hồ sơ vay giải ngân tự động phải có xác suất vỡ nợ thấp (Probability of Default < 2.5%). Ngăn ngừa triệt để hiện tượng nợ xấu bùng phát do nới lỏng điều kiện thẩm định thu nhập.', N'Phòng Kinh doanh liên tục gây áp lực đòi hạ điểm chuẩn tín dụng để chạy đua số lượng giải ngân; các khoản vay duyệt tự động không kiểm tra kỹ bị nợ xấu chỉ sau 2 tháng đầu. Nhiều đối tượng vay sử dụng thủ thuật "vẽ" sao kê ngân hàng và bảng lương giả rất khó phát hiện bằng mắt thường.', N'Rủi ro FinNova bị các tổ chức xếp hạng tín nhiệm hạ bậc và chi phí trích lập dự phòng rủi ro tín dụng tăng vọt làm ăn mòn toàn bộ lợi nhuận.', N'Thận trọng, phân tích dựa trên dữ liệu thống kê (Default Rate, Vintage Curve, Loss Given Default, Gini Coefficient).', N'Nguyên tắc, bảo thủ, kiên định bảo vệ an toàn vốn, không bao giờ nhượng bộ trước các đề xuất tăng trưởng nóng.', 1, 1
    );
END;

-- 4. Seed Knowledge Items & Stakeholder Access
IF NOT EXISTS (SELECT 1 FROM [scenario].[KnowledgeItems] WHERE [ScenarioVersionId] = @ScenarioVersionId_FIN_001_V1 AND [Code] = N'K-FIN-01')
BEGIN
    INSERT INTO [scenario].[KnowledgeItems] ([ScenarioVersionId], [Code], [Title], [Content], [Category], [Importance], [CreatedAt])
    VALUES (@ScenarioVersionId_FIN_001_V1, N'K-FIN-01', N'Kiến trúc Phễu Thẩm định Đa tầng (Multi-Tier Underwriting Funnel)', N'Để không lãng phí chi phí tra cứu dữ liệu trả phí (đặc biệt là chi phí truy vấn cổng CIC khoảng 30.000đ - 50.000đ/lượt) và đẩy nhanh tốc độ duyệt đơn, quy trình Digital LOS chia việc thẩm định thành 4 tầng phễu tuần tự (Funnel Tiers):

1. Tầng 1 - Sàng lọc tiêu chí cứng nội bộ (Hard Rules & Internal Blacklist):
   - Kiểm tra ngay trên database nội bộ: Độ tuổi (20-55 tuổi), khu vực hỗ trợ, kiểm tra xem khách có nằm trong danh sách đen nội bộ hoặc đang có nợ quá hạn tại FinNova hay không. Thời gian xử lý < 200ms. Chi phí: 0 đồng.
   - Nếu trượt tầng 1 -> DỪNG NGAY và từ chối hồ sơ, không gọi bất kỳ API nào khác.
2. Tầng 2 - Xác thực định danh & Chống giả mạo eKYC:
   - Quét OCR giấy tờ, kiểm tra Liveness khuôn mặt và so khớp ảnh chân dung với ảnh CCCD. Kiểm tra dấu hiệu giả lập thiết bị di động (Device Fingerprint). Thời gian < 3 giây.
   - Nếu trượt tầng 2 -> DỪNG NGAY và đánh dấu cờ gian lận.
3. Tầng 3 - Tra cứu Dữ liệu Viễn thông & Dữ liệu Thay thế giá rẻ:
   - Gọi API chấm điểm nhà mạng (Telco Score, dữ liệu nạp tiền, tuổi thọ SIM) với chi phí thấp (khoảng 3.000đ/lượt).
   - Nếu điểm viễn thông quá thấp (dưới ngưỡng tối thiểu) -> DỪNG NGAY.
4. Tầng 4 - Tra cứu Lịch sử Tín dụng CIC & Chấm điểm Tín dụng Tổng hợp:
   - Chỉ những hồ sơ đã vượt qua xuất sắc cả 3 tầng trên mới được cấp phép gọi API tra cứu nợ xấu tại CIC và nạp vào Decision Engine để tính toán hạn mức vay cuối cùng.
   - Mô hình này giúp tiết kiệm 42% tổng ngân sách tra cứu dữ liệu hàng tháng cho FinNova.', N'Process', N'Critical', SYSDATETIMEOFFSET());
END;
