DECLARE @PId_FIN_001_V1_K_FIN_03_LEGAL_MGR int = (SELECT [Id] FROM [scenario].[StakeholderPersonas] WHERE [ScenarioVersionId] = @ScenarioVersionId_FIN_001_V1 AND [Name] = N'Phạm Quốc Huy');
