    ) VALUES (
        @ScenarioVersionId_RET_001_V1, N'Phạm Thế Anh', N'IT Integration Lead', N'Công nghệ thông tin', N'Quản trị hạ tầng hệ thống thông tin bán lẻ, thiết kế giao thức API kết nối giữa Central Promo Engine, Mobile App và máy tính tiền POS tại cửa hàng.',
        N'Đảm bảo độ trễ API kiểm tra khuyến mãi < 200ms và chịu tải tối thiểu 1.500 TPS vào các khung giờ Flash Sale. Bảo đảm tính toàn vẹn dữ liệu tập trung, chống tấn công dò mã voucher (Brute-force) và bảo mật thông tin hội viên.', N'Phần mềm POS tại 65 cửa hàng là ứng dụng Windows Desktop cũ (.NET WinForms), cơ sở dữ liệu MS SQL Express cục bộ rất dễ bị treo khi nhận lượng lớn dữ liệu đồng bộ. Phòng Marketing liên tục đưa ra các kịch bản khuyến mãi quái chiêu khiến kiến trúc cơ sở dữ liệu phải viết lại liên tục.', N'Chi phí duy trì hạ tầng Cloud tăng vọt nếu thiết kế luồng kiểm tra API không tối ưu; rủi ro lộ lọt API Secret Key từ các máy POS tại chi nhánh.', N'Điềm đạm, dùng nhiều thuật ngữ kiến trúc phần mềm (Payload, Latency, Webhook, Idempotency, Event-driven, Rollback). Luôn đòi hỏi số liệu kỹ thuật chính xác.', N'Logic, cẩn trọng, chỉ đồng thuận khi giải pháp có bằng chứng khả thi về mặt hiệu năng và cơ chế an toàn dự phòng (Failover).', 4, 1
    );
END;
IF NOT EXISTS (SELECT 1 FROM [scenario].[StakeholderPersonas] WHERE [ScenarioVersionId] = @ScenarioVersionId_RET_001_V1 AND [Name] = N'Vũ Bích Ngọc')
BEGIN
    INSERT INTO [scenario].[StakeholderPersonas] (
        [ScenarioVersionId], [Name], [StakeholderRole], [Department], [Responsibilities],
        [Goals], [PainPoints], [BusinessConcerns], [CommunicationStyle], [Personality], [DisplayOrder], [IsActive]
    ) VALUES (
        @ScenarioVersionId_RET_001_V1, N'Vũ Bích Ngọc', N'Head of Marketing & Loyalty', N'Marketing', N'Xây dựng chiến lược khuyến mãi, quản trị chương trình khách hàng thân thiết MegaClub và tối ưu hóa tỷ lệ chuyển đổi mua hàng đa kênh.',
        N'Tăng tỷ lệ giữ chân khách hàng (Customer Retention) và tần suất mua hàng lặp lại. Muốn linh hoạt tạo ra các kịch bản khuyến mãi phức tạp (mua kèm combo, voucher sinh nhật, flash sale) mà không phụ thuộc đội IT lập trình cứng. Muốn khách mua tại cửa hàng là điểm nhảy lên App ngay lập tức để kích thích đặt tiếp đơn online.', N'Khách hàng VIP thường xuyên phàn nàn vì mua hàng tại showroom cả ngày rồi mà trên App vẫn chưa thấy thăng hạng hội viên. Liên tục bị phòng Tài chính phàn nàn vì các kịch bản khuyến mãi làm vượt trần ngân sách chiết khấu.', N'Lo ngại nếu đưa ra các quy định kiểm soát quá khắt khe (bắt xác thực OTP nhiều bước, giới hạn nhập mã) sẽ làm giảm mạnh tỷ lệ hoàn tất đơn hàng (Checkout Conversion Rate).', N'Năng động, hào hứng, nói nhiều thuật ngữ Marketing (LTV, CAC, Retention, Gamification, Push Notification). Thường đưa ra yêu cầu mang tính khái niệm rộng.', N'Hướng ngoại, quyết đoán, ưu tiên trải nghiệm khách hàng và doanh số ngắn hạn, ít kiên nhẫn với các thủ tục kiểm soát kế toán.', 1, 1
    );
END;
IF NOT EXISTS (SELECT 1 FROM [scenario].[StakeholderPersonas] WHERE [ScenarioVersionId] = @ScenarioVersionId_RET_001_V1 AND [Name] = N'Lê Trọng Nghĩa')
BEGIN
    INSERT INTO [scenario].[StakeholderPersonas] (
        [ScenarioVersionId], [Name], [StakeholderRole], [Department], [Responsibilities],
        [Goals], [PainPoints], [BusinessConcerns], [CommunicationStyle], [Personality], [DisplayOrder], [IsActive]
    ) VALUES (
        @ScenarioVersionId_RET_001_V1, N'Lê Trọng Nghĩa', N'Retail Store Operations Director', N'Vận hành Bán lẻ', N'Quản lý tiêu chuẩn dịch vụ khách hàng, quy trình bán hàng tại quầy thu ngân và bảo đảm chỉ tiêu doanh số của 65 showroom MegaFashion.',
        N'Thời gian thanh toán một khách hàng tại quầy POS không vượt quá 45 giây. Khách hàng không phải xếp hàng chờ đợi lâu; giảm áp lực sai sót tính tiền cho nhân viên thu ngân mới. Hệ thống bán lẻ tại cửa hàng phải tiếp tục bán được hàng ngay cả khi mất kết nối mạng Internet.', N'Mỗi đợt sale lớn, máy POS tính toán mã ưu đãi chậm rì, quay vòng tròn làm khách cáu gắt và chửi bới nhân viên quầy. Quy trình đổi trả hàng quá phức tạp, thu ngân phải lấy máy tính bỏ túi bấm tay chia tỷ lệ chiết khấu rồi xin chữ ký 3 bên làm mất thời gian.', N'Doanh thu showroom bị sụt giảm nghiêm trọng nếu hệ thống kiểm tra voucher online làm nghẽn toàn bộ quầy thanh toán vào giờ cao điểm cuối tuần.', N'Bộc trực, thực tế, hay nói về áp lực hiện trường: "Các bạn ngồi phòng lạnh vẽ quy trình, xuống quầy đứng 1 tiếng ca tối xem khách họ có la làng không?".', N'Hành động nhanh, bảo vệ nhân viên tuyến đầu, cảnh giác với các công nghệ làm phức tạp thêm thao tác thu ngân.', 3, 1
    );
END;

-- 4. Seed Knowledge Items & Stakeholder Access
IF NOT EXISTS (SELECT 1 FROM [scenario].[KnowledgeItems] WHERE [ScenarioVersionId] = @ScenarioVersionId_RET_001_V1 AND [Code] = N'K-RET-01')
BEGIN
    INSERT INTO [scenario].[KnowledgeItems] ([ScenarioVersionId], [Code], [Title], [Content], [Category], [Importance], [CreatedAt])
    VALUES (@ScenarioVersionId_RET_001_V1, N'K-RET-01', N'Cơ chế Khóa tạm Voucher (Two-Phase Voucher Hold)', N'Để ngăn chặn hoàn toàn việc khách hàng áp dụng cùng một mã voucher 1 lần (Single-use) đồng thời trên website và tại quầy thu ngân trong thời gian trễ đồng bộ, hệ thống Promo Engine trung tâm cần triển khai cơ chế Two-Phase Hold:

1. Giai đoạn 1 (Hold Phase): Ngay khi khách hàng nhập mã voucher vào giỏ hàng online hoặc nhân viên thu ngân quét mã barcode voucher tại máy POS, hệ thống gửi lệnh API `POST /api/vouchers/hold`. Voucher lập tức chuyển sang trạng thái `HOLD` kèm khóa phân tán (Distributed Lock qua Redis) trong thời hạn tối đa 15 phút. Trong thời gian này, bất kỳ kênh nào khác cố tình sử dụng mã này đều nhận phản hồi lỗi `VOUCHER_CURRENTLY_LOCKED`.
2. Giai đoạn 2 (Commit Phase): Khi khách thanh toán thành công, hệ thống gửi lệnh `POST /api/vouchers/redeem` để chuyển voucher sang trạng thái vĩnh viễn `USED` kèm ID hóa đơn thanh toán.
3. Cơ chế Tự động Nhả (Auto-Release): Nếu sau 15 phút mà đơn hàng online chưa thanh toán hoặc giỏ hàng POS bị thu ngân hủy (Cancel Bill), Redis TTL hết hạn và hệ thống tự động hoàn trả voucher về trạng thái `ACTIVE` cho khách hàng.', N'System', N'Critical', SYSDATETIMEOFFSET());
END;
