BEGIN
    INSERT INTO [scenario].[ScenarioEvents] ([ScenarioVersionId], [Title], [Description], [TriggerType], [TriggerConditionJson], [EventContent], [DisplayOrder], [IsActive])
    VALUES (@ScenarioVersionId_RET_001_V1, N'Sự cố đứt mạng diện rộng tại chuỗi Showroom giờ cao điểm (Event E2)', N'18 showroom lớn tại Hà Nội và TP.HCM đồng loạt mất kết nối Internet do sự cố nhà mạng viễn thông đúng vào tối thứ Bảy giờ vàng.', N'Manual', NULL, N'Đúng vào khung giờ vàng 19h30 tối thứ Bảy, tuyến cáp quang chính của đơn vị cung cấp dịch vụ Internet bị sự cố khiến 18 showroom MegaFashion lớn nhất tại Hà Nội và TP.HCM mất toàn bộ kết nối ra bên ngoài.

Khách hàng tập trung đông nghẹt tại quầy thu ngân để thanh toán nhưng phần mềm POS không thể gọi API Central Promo Engine để kiểm tra mã giảm giá và điểm tích lũy MegaClub.

Nhân viên thu ngân bị khách hàng phàn nàn gay gắt vì không cho áp dụng voucher đã lưu trên ứng dụng điện thoại. Cửa hàng trưởng các chi nhánh liên tục gọi điện cầu cứu Giám đốc Vận hành yêu cầu cho phép giảm giá thủ công bằng miệng để giải tỏa áp lực đám đông.', 2, 1);
