IF NOT EXISTS (SELECT 1 FROM [scenario].[KnowledgeItems] WHERE [ScenarioVersionId] = @ScenarioVersionId_OMNI_001_V1 AND [Code] = N'K-IT-02')
BEGIN
    INSERT INTO [scenario].[KnowledgeItems] ([ScenarioVersionId], [Code], [Title], [Content], [Category], [Importance], [CreatedAt])
    VALUES (@ScenarioVersionId_OMNI_001_V1, N'K-IT-02', N'Cơ chế dự phòng khi đứt cáp mạng tại cửa hàng (Offline Mode)', N'Để đảm bảo cửa hàng vẫn bán được hàng khi mất kết nối Internet, phần mềm POS có tính năng "Chế độ Ngoại tuyến" (Offline Mode):
- Máy POS vẫn cho phép quét mã vạch và in hóa đơn bình thường dựa trên dữ liệu tồn kho được lưu cục bộ (local SQLite cache).
- Mọi giao dịch bán offline được ghi nhận vào hàng đợi (Queue) tại máy thu ngân.
- Khi có mạng trở lại, hàng đợi này sẽ tự động đẩy lên server trung tâm.

Rủi ro lớn: Trong thời gian mất mạng (có khi kéo dài nửa ngày ở các vùng mưa bão), tồn kho cục bộ có thể đã bán hết nhưng trên Website vẫn hiển thị "Còn hàng", dẫn tới việc khách online tiếp tục đặt mua -> Tạo ra đơn trùng và thiếu hàng nghiêm trọng.', N'System', N'High', SYSDATETIMEOFFSET());
END;
