    INSERT INTO [scenario].[KnowledgeItems] ([ScenarioVersionId], [Code], [Title], [Content], [Category], [Importance], [CreatedAt])
    VALUES (@ScenarioVersionId_OMNI_001_V1, N'K-SAL-02', N'Cơ chế gán cửa hàng fulfill gần nhất (Order Routing Logic)', N'Kênh Sales cam kết dịch vụ "Giao nhanh 2 giờ" cho khách hàng nội thành. Để đạt được cam kết này, hệ thống phải tự động định tuyến đơn hàng về cửa hàng gần địa chỉ người nhận nhất còn đủ hàng.

Nếu cửa hàng gần nhất hết hàng mà hệ thống báo ảo (do POS chậm đồng bộ), đơn sẽ bị chuyển lòng vòng sang cửa hàng khác xa hơn, làm trễ hẹn 2 giờ và khách hàng thường hủy đơn ngay lập tức.', N'Process', N'High', SYSDATETIMEOFFSET());
END;
